import { Router, type Request, type Response } from 'express';
import { randomUUID } from 'node:crypto';

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  if (typeof data !== 'object' || data === null) {
    return false;
  }

  const candidate = data as Record<string, unknown>;

  if (typeof candidate.url !== 'string') {
    return false;
  }

  if ('title' in candidate && candidate.title !== undefined && typeof candidate.title !== 'string') {
    return false;
  }

  if ('tags' in candidate && candidate.tags !== undefined) {
    if (!Array.isArray(candidate.tags)) {
      return false;
    }
    for (const tag of candidate.tags) {
      if (typeof tag !== 'string') {
        return false;
      }
    }
  }

  return true;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(['/', '/bookmarks', '/api/v1/bookmarks'], (req: Request, res: Response) => {
  const body: unknown = req.body;

  if (!isCreateBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid request body' });
    return;
  }

  const newBookmark: Bookmark = {
    id: randomUUID(),
    url: body.url,
    ...(body.title !== undefined ? { title: body.title } : {}),
    tags: body.tags ?? [],
    createdAt: new Date().toISOString(),
  };

  res.status(201).json(newBookmark);
});

export default bookmarksRouter;

import { Router, type Request, type Response } from 'express';
import { randomUUID } from 'node:crypto';
import { z } from 'zod';

export const createBookmarkSchema = z.object({
  url: z
    .string({ required_error: 'URL is required' })
    .url({ message: 'Must be a valid URL' })
    .max(2048, { message: 'URL must be 2048 characters or less' }),
  title: z
    .string()
    .max(200, { message: 'Title must be 200 characters or less' })
    .optional(),
  tags: z
    .array(z.string().max(50, { message: 'Each tag must be 50 characters or less' }))
    .max(10, { message: 'Tags cannot exceed 10 items' })
    .optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(data).success;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(['/', '/bookmarks', '/api/v1/bookmarks'], (req: Request, res: Response) => {
  const body: unknown = req.body;
  const parseResult = createBookmarkSchema.safeParse(body);

  if (!parseResult.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: parseResult.error.flatten(),
    });
    return;
  }

  const { url, title, tags } = parseResult.data;

  const newBookmark: Bookmark = {
    id: randomUUID(),
    url,
    ...(title !== undefined ? { title } : {}),
    tags: tags ?? [],
    createdAt: new Date().toISOString(),
  };

  res.status(201).json(newBookmark);
});

export default bookmarksRouter;

