import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  create(dto: CreateBookmarkDTO): Bookmark {
    const existing = this.findByUrl(dto.url);
    if (existing) {
      throw new DuplicateBookmarkError(`Bookmark with URL already exists: ${dto.url}`);
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      tags: dto.tags ? [...dto.tags] : [],
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  findById(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  DuplicateBookmarkError,
  type Bookmark,
} from '../services/bookmark-service.js';

export { Bookmark, DuplicateBookmarkError };

export const createBookmarkSchema = z.object({
  url: z
    .string({ message: 'URL is required' })
    .url({ message: 'Must be a valid URL' })
    .max(2048, { message: 'URL must be 2048 characters or less' }),
  title: z
    .string()
    .max(200, { message: 'Title must be 200 characters or less' })
    .optional(),
  tags: z
    .array(z.string().max(50, { message: 'Each tag must be 50 characters or less' }))
    .max(10, { message: 'Tags cannot exceed 10 items' })
    .optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(data).success;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(
  ['/', '/bookmarks', '/api/v1/bookmarks'],
  (req: Request, res: Response, next: NextFunction) => {
    const body: unknown = req.body;
    const parseResult = createBookmarkSchema.safeParse(body);

    if (!parseResult.success) {
      res.status(400).json({
        error: 'Validation failed',
        details: parseResult.error.flatten(),
      });
      return;
    }

    try {
      const newBookmark = bookmarkService.create(parseResult.data);
      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      if (err instanceof DuplicateBookmarkError) {
        res.status(409).json({ error: err.message });
        return;
      }
      next(err);
    }
  }
);

export default bookmarksRouter;

import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError } from '../services/bookmark-service.js';

export function isInvalidJsonError(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) {
    return false;
  }
  const candidate = err as Record<string, unknown>;
  return (
    candidate.type === 'entity.parse.failed' ||
    (err instanceof SyntaxError &&
      (candidate.status === 400 || candidate.statusCode === 400))
  );
}

export function isZodError(err: unknown): err is ZodError {
  if (err instanceof ZodError) {
    return true;
  }
  if (typeof err === 'object' && err !== null) {
    const candidate = err as Record<string, unknown>;
    return (
      candidate.name === 'ZodError' &&
      (Array.isArray(candidate.issues) || Array.isArray(candidate.errors))
    );
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  next: NextFunction
): void {
  if (res.headersSent) {
    next(err);
    return;
  }

  if (isInvalidJsonError(err)) {
    res.status(400).json({
      error: 'Invalid JSON',
    });
    return;
  }

  if (isZodError(err)) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.errors,
    });
    return;
  }

  if (
    err instanceof DuplicateBookmarkError ||
    (typeof err === 'object' &&
      err !== null &&
      (err as Record<string, unknown>).name === 'DuplicateBookmarkError')
  ) {
    const message =
      err instanceof Error ? err.message : 'Bookmark already exists';
    res.status(409).json({
      error: message,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal server error',
  });
}

export default errorHandler;

