import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  DuplicateBookmarkError,
  type Bookmark,
} from '../services/bookmark-service.js';

export { Bookmark, DuplicateBookmarkError };

export const createBookmarkSchema = z.object({
  url: z
    .string({ message: 'URL is required' })
    .url({ message: 'Must be a valid URL' })
    .max(2048, { message: 'URL must be 2048 characters or less' }),
  title: z
    .string()
    .max(200, { message: 'Title must be 200 characters or less' })
    .optional(),
  tags: z
    .array(z.string().max(50, { message: 'Each tag must be 50 characters or less' }))
    .max(10, { message: 'Tags cannot exceed 10 items' })
    .optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(data).success;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(
  ['/', '/bookmarks', '/api/v1/bookmarks'],
  (req: Request, res: Response, next: NextFunction) => {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        return next(parseResult.error);
      }

      const newBookmark = bookmarkService.create(parseResult.data);
      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  }
);

export default bookmarksRouter;

