import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError } from '../services/bookmark-service.js';

export function isInvalidJsonError(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) {
    return false;
  }
  const candidate = err as Record<string, unknown>;
  return (
    candidate.type === 'entity.parse.failed' ||
    (err instanceof SyntaxError &&
      (candidate.status === 400 || candidate.statusCode === 400))
  );
}

export function isZodError(err: unknown): err is ZodError {
  if (err instanceof ZodError) {
    return true;
  }
  if (typeof err === 'object' && err !== null) {
    const candidate = err as Record<string, unknown>;
    return (
      candidate.name === 'ZodError' &&
      (Array.isArray(candidate.issues) || Array.isArray(candidate.errors))
    );
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  next: NextFunction
): void {
  if (res.headersSent) {
    next(err);
    return;
  }

  if (isInvalidJsonError(err)) {
    res.status(400).json({
      error: 'Invalid JSON',
    });
    return;
  }

  if (isZodError(err)) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.issues,
    });
    return;
  }

  if (
    err instanceof DuplicateBookmarkError ||
    (typeof err === 'object' &&
      err !== null &&
      (err as Record<string, unknown>).name === 'DuplicateBookmarkError')
  ) {
    const message =
      err instanceof Error ? err.message : 'Bookmark already exists';
    res.status(409).json({
      error: message,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal server error',
  });
}

export default errorHandler;

import express from 'express';
import { bookmarksRouter } from './routes/bookmarks.js';
import { errorHandler } from './middleware/error-handler.js';

export const app = express();

app.use(express.json());

app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

app.use('/api/v1/bookmarks', bookmarksRouter);

app.use(errorHandler);

export default app;

