import express from 'express';
import { bookmarksRouter } from './routes/bookmarks.js';
import { errorHandler } from './middleware/error-handler.js';

export const app = express();

app.use(express.json());

app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

app.use('/api/v1/bookmarks', bookmarksRouter);

app.use(errorHandler);

export default app;

import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(message = 'Bookmark not found') {
    super(message);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  create(dto: CreateBookmarkDTO): Bookmark {
    const existing = this.findByUrl(dto.url);
    if (existing) {
      throw new DuplicateBookmarkError(`Bookmark with URL already exists: ${dto.url}`);
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      tags: dto.tags ? [...dto.tags] : [],
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  findById(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import {
  DuplicateBookmarkError,
  BookmarkNotFoundError,
} from '../services/bookmark-service.js';

export function isInvalidJsonError(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) {
    return false;
  }
  const candidate = err as Record<string, unknown>;
  return (
    candidate.type === 'entity.parse.failed' ||
    (err instanceof SyntaxError &&
      (candidate.status === 400 || candidate.statusCode === 400))
  );
}

export function isZodError(err: unknown): err is ZodError {
  if (err instanceof ZodError) {
    return true;
  }
  if (typeof err === 'object' && err !== null) {
    const candidate = err as Record<string, unknown>;
    return (
      candidate.name === 'ZodError' &&
      (Array.isArray(candidate.issues) || Array.isArray(candidate.errors))
    );
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  next: NextFunction
): void {
  if (res.headersSent) {
    next(err);
    return;
  }

  if (isInvalidJsonError(err)) {
    res.status(400).json({
      error: 'Invalid JSON',
    });
    return;
  }

  if (isZodError(err)) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.issues,
    });
    return;
  }

  if (
    err instanceof DuplicateBookmarkError ||
    (typeof err === 'object' &&
      err !== null &&
      (err as Record<string, unknown>).name === 'DuplicateBookmarkError')
  ) {
    const message =
      err instanceof Error ? err.message : 'Bookmark already exists';
    res.status(409).json({
      error: message,
    });
    return;
  }

  if (
    err instanceof BookmarkNotFoundError ||
    (typeof err === 'object' &&
      err !== null &&
      (err as Record<string, unknown>).name === 'BookmarkNotFoundError')
  ) {
    const message =
      err instanceof Error ? err.message : 'Bookmark not found';
    res.status(404).json({
      error: message,
    });
    return;
  }

  res.status(500).json({
    error: 'Internal server error',
  });
}

export default errorHandler;

