describe('createBookmarkSchema', () => {
  it('should accept valid inputs with required fields only', () => {
    const input: unknown = {
      url: 'https://example.com',
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com');
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should accept valid inputs with title and tags', () => {
    const input: unknown = {
      url: 'https://example.com/docs',
      title: 'Documentation',
      tags: ['docs', 'api', 'v1'],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com/docs');
      expect(result.data.title).toBe('Documentation');
      expect(result.data.tags).toEqual(['docs', 'api', 'v1']);
    }
  });

  it('should accept valid inputs at maximum allowed boundaries', () => {
    const maxTitle = 'a'.repeat(200);
    const maxTag = 'b'.repeat(50);
    const input: unknown = {
      url: 'https://example.com/edge-case',
      title: maxTitle,
      tags: Array.from({ length: 10 }, () => maxTag),
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
  });

  it('should fail validation on missing url', () => {
    const input: unknown = {
      title: 'Missing URL',
      tags: ['test'],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issuePaths = result.error.issues.map((i) => i.path.join('.'));
      expect(issuePaths).toContain('url');
    }
  });

  it('should fail validation on url too long', () => {
    const longUrl = `https://example.com/${'a'.repeat(2048)}`;
    const input: unknown = {
      url: longUrl,
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issuePaths = result.error.issues.map((i) => i.path.join('.'));
      expect(issuePaths).toContain('url');
    }
  });

  it('should fail validation on invalid url format', () => {
    const input: unknown = {
      url: 'not-a-valid-url',
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issuePaths = result.error.issues.map((i) => i.path.join('.'));
      expect(issuePaths).toContain('url');
    }
  });

  it('should fail validation when there are too many tags', () => {
    const input: unknown = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_, i) => `tag${i}`),
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issuePaths = result.error.issues.map((i) => i.path.join('.'));
      expect(issuePaths).toContain('tags');
    }
  });

  it('should fail validation when a tag is too long', () => {
    const input: unknown = {
      url: 'https://example.com',
      tags: ['valid-tag', 'a'.repeat(51)],
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issuePaths = result.error.issues.map((i) => i.path.join('.'));
      expect(issuePaths).toContain('tags.1');
    }
  });

  it('should fail validation when title is too long', () => {
    const input: unknown = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };

    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issuePaths = result.error.issues.map((i) => i.path.join('.'));
      expect(issuePaths).toContain('title');
    }
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with generated id and createdAt timestamp', () => {
      const bookmark = service.create({
        url: 'https://example.com',
      });

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id).toMatch(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
      );
      expect(bookmark.url).toBe('https://example.com');
      expect(bookmark.tags).toEqual([]);
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.createdAt).toBeDefined();
      expect(new Date(bookmark.createdAt).toISOString()).toBe(bookmark.createdAt);
    });

    it('should store title and tags when provided', () => {
      const bookmark = service.create({
        url: 'https://example.com/docs',
        title: 'Documentation',
        tags: ['docs', 'api'],
      });

      expect(bookmark.url).toBe('https://example.com/docs');
      expect(bookmark.title).toBe('Documentation');
      expect(bookmark.tags).toEqual(['docs', 'api']);
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating a bookmark with an identical URL', () => {
      service.create({
        url: 'https://example.com/duplicate',
        title: 'Original',
      });

      expect(() => {
        service.create({
          url: 'https://example.com/duplicate',
          title: 'Duplicate attempt',
        });
      }).toThrow(DuplicateBookmarkError);
    });

    it('should include the conflicting URL in the duplicate error message', () => {
      const url = 'https://example.com/same-url';
      service.create({ url });

      try {
        service.create({ url });
        expect.unreachable('Should have thrown DuplicateBookmarkError');
      } catch (err: unknown) {
        expect(err).toBeInstanceOf(DuplicateBookmarkError);
        if (err instanceof DuplicateBookmarkError) {
          expect(err.message).toContain(url);
        }
      }
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by its ID via getById and findById', () => {
      const created = service.create({
        url: 'https://example.com/retrieve',
        title: 'Retrieve Test',
      });

      const retrieved1 = service.getById(created.id);
      expect(retrieved1).toEqual(created);

      const retrieved2 = service.findById(created.id);
      expect(retrieved2).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent ID', () => {
      expect(service.getById('non-existent-id')).toBeUndefined();
      expect(service.findById('non-existent-id')).toBeUndefined();
    });

    it('should retrieve a bookmark by its URL via findByUrl', () => {
      const created = service.create({
        url: 'https://example.com/by-url',
        title: 'Find By URL',
      });

      const retrieved = service.findByUrl('https://example.com/by-url');
      expect(retrieved).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent URL', () => {
      expect(service.findByUrl('https://non-existent.com')).toBeUndefined();
    });

    it('should retrieve all stored bookmarks via getAll', () => {
      const b1 = service.create({ url: 'https://example.com/1' });
      const b2 = service.create({ url: 'https://example.com/2' });

      const all = service.getAll();
      expect(all).toHaveLength(2);
      expect(all.map((b) => b.id)).toContain(b1.id);
      expect(all.map((b) => b.id)).toContain(b2.id);
    });

    it('should delete a bookmark by ID and clear all entries', () => {
      const created = service.create({ url: 'https://example.com/delete-me' });
      expect(service.getById(created.id)).toBeDefined();

      const deleted = service.delete(created.id);
      expect(deleted).toBe(true);
      expect(service.getById(created.id)).toBeUndefined();

      service.create({ url: 'https://example.com/stay' });
      expect(service.getAll()).toHaveLength(1);
      service.clear();
      expect(service.getAll()).toHaveLength(0);
    });
  });
});

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import {
  bookmarkService,
  BookmarkService,
  DuplicateBookmarkError,
  BookmarkNotFoundError,
  type Bookmark,
} from '../services/bookmark-service.js';

export { Bookmark, DuplicateBookmarkError, BookmarkNotFoundError };

export const createBookmarkSchema = z.object({
  url: z
    .string({ message: 'URL is required' })
    .url({ message: 'Must be a valid URL' })
    .max(2048, { message: 'URL must be 2048 characters or less' }),
  title: z
    .string()
    .max(200, { message: 'Title must be 200 characters or less' })
    .optional(),
  tags: z
    .array(z.string().max(50, { message: 'Each tag must be 50 characters or less' }))
    .max(10, { message: 'Tags cannot exceed 10 items' })
    .optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export function isCreateBookmarkInput(data: unknown): data is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(data).success;
}

export const bookmarksRouter = Router();

bookmarksRouter.post(
  ['/', '/bookmarks', '/api/v1/bookmarks'],
  (req: Request, res: Response, next: NextFunction) => {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        return next(parseResult.error);
      }

      const newBookmark = bookmarkService.create(parseResult.data);
      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  }
);

bookmarksRouter.get(
  ['/', '/bookmarks', '/api/v1/bookmarks'],
  (_req: Request, res: Response, next: NextFunction) => {
    try {
      const bookmarks = bookmarkService.getAll();
      res.status(200).json(bookmarks);
    } catch (err: unknown) {
      next(err);
    }
  }
);

bookmarksRouter.get(
  ['/:id', '/bookmarks/:id', '/api/v1/bookmarks/:id'],
  (req: Request, res: Response, next: NextFunction) => {
    try {
      const rawId = req.params.id;
      const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : undefined;
      if (!id) {
        return res.status(404).json({ error: 'Bookmark not found' });
      }

      const bookmark = bookmarkService.getById(id);
      if (!bookmark) {
        return res.status(404).json({ error: 'Bookmark not found' });
      }

      res.status(200).json(bookmark);
    } catch (err: unknown) {
      next(err);
    }
  }
);

export default bookmarksRouter;

