interface BookmarkResponseBody {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

function isBookmarkResponse(value: unknown): value is BookmarkResponseBody {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === 'string' &&
    typeof candidate.url === 'string' &&
    (candidate.title === undefined || typeof candidate.title === 'string') &&
    Array.isArray(candidate.tags) &&
    typeof candidate.createdAt === 'string'
  );
}

function isBookmarkResponseArray(value: unknown): value is BookmarkResponseBody[] {
  return Array.isArray(value) && value.every(isBookmarkResponse);
}

describe('Bookmarks API integration tests (supertest)', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should create a new bookmark with title and tags and return 201', async () => {
      const payload = {
        url: 'https://example.com/post-test',
        title: 'Post Test',
        tags: ['news', 'tech'],
      };

      const res = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload)
        .set('Content-Type', 'application/json');

      expect(res.status).toBe(201);
      const body: unknown = res.body;
      expect(isBookmarkResponse(body)).toBe(true);
      if (isBookmarkResponse(body)) {
        expect(body.id).toBeDefined();
        expect(body.url).toBe(payload.url);
        expect(body.title).toBe(payload.title);
        expect(body.tags).toEqual(payload.tags);
        expect(body.createdAt).toBeDefined();
      }
    });

    it('should create a bookmark with required url only and return 201', async () => {
      const res = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/minimal' })
        .set('Content-Type', 'application/json');

      expect(res.status).toBe(201);
      const body: unknown = res.body;
      expect(isBookmarkResponse(body)).toBe(true);
      if (isBookmarkResponse(body)) {
        expect(body.url).toBe('https://example.com/minimal');
        expect(body.title).toBeUndefined();
        expect(body.tags).toEqual([]);
      }
    });
  });

  describe('GET /api/v1/bookmarks', () => {
    it('should return empty list when no bookmarks exist', async () => {
      const res = await request(app).get('/api/v1/bookmarks');

      expect(res.status).toBe(200);
      const body: unknown = res.body;
      expect(Array.isArray(body)).toBe(true);
      expect(body).toEqual([]);
    });

    it('should return all bookmarks sorted by createdAt descending', async () => {
      const res1 = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/first', title: 'First' });
      expect(res1.status).toBe(201);

      const res2 = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/second', title: 'Second' });
      expect(res2.status).toBe(201);

      const res = await request(app).get('/api/v1/bookmarks');
      expect(res.status).toBe(200);

