function isBookmarkResponseArray(value: unknown): value is BookmarkResponseBody[] {
  return Array.isArray(value) && value.every(isBookmarkResponse);
}

interface PaginatedResponse {
  data: BookmarkResponseBody[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

function isPaginatedBookmarksResponse(value: unknown): value is PaginatedResponse {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  if (!Array.isArray(candidate.data) || !candidate.data.every(isBookmarkResponse)) {
    return false;
  }
  if (typeof candidate.pagination !== 'object' || candidate.pagination === null) {
    return false;
  }
  const pag = candidate.pagination as Record<string, unknown>;
  return (
    typeof pag.page === 'number' &&
    typeof pag.limit === 'number' &&
    typeof pag.total === 'number' &&
    typeof pag.totalPages === 'number'
  );
}

