  let consoleSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    consoleSpy.mockRestore();
  });

  it('should log method, path, status, and duration_ms in JSON format', async () => {
    const testApp = express();
    testApp.use(requestLogger);
    testApp.get('/test-route', (_req, res) => {
      res.status(200).json({ ok: true });
    });

    const res = await request(testApp).get('/test-route');
    expect(res.status).toBe(200);

    expect(consoleSpy).toHaveBeenCalledOnce();
    const logOutput = consoleSpy.mock.calls[0]?.[0];
    expect(typeof logOutput).toBe('string');

    const parsed: unknown = JSON.parse(logOutput as string);
    expect(typeof parsed).toBe('object');
    expect(parsed).not.toBeNull();

    const entry = parsed as Partial<RequestLogEntry>;
    expect(entry.method).toBe('GET');
    expect(entry.path).toBe('/test-route');
    expect(entry.status).toBe(200);
    expect(typeof entry.duration_ms).toBe('number');
    expect(entry.duration_ms).toBeGreaterThanOrEqual(0);
  });

  it('should strip query parameters and log path only', async () => {
    const testApp = express();
    testApp.use(requestLogger);
    testApp.get('/api/search', (_req, res) => {
      res.status(200).send('done');
    });

    await request(testApp).get('/api/search?q=test&limit=10');

    expect(consoleSpy).toHaveBeenCalledOnce();
    const logOutput = consoleSpy.mock.calls[0]?.[0] as string;
    const entry = JSON.parse(logOutput) as RequestLogEntry;

    expect(entry.path).toBe('/api/search');
    expect(entry.status).toBe(200);
  });

  it('should log correct status for 404 and 500 responses', async () => {
    const testApp = express();
    testApp.use(requestLogger);
    testApp.get('/error', (_req, res) => {
      res.status(500).send('server error');
    });

    await request(testApp).get('/error');
    await request(testApp).get('/not-found');

    expect(consoleSpy).toHaveBeenCalledTimes(2);

    const first = JSON.parse(consoleSpy.mock.calls[0]?.[0] as string) as RequestLogEntry;
    expect(first.status).toBe(500);
    expect(first.path).toBe('/error');

    const second = JSON.parse(consoleSpy.mock.calls[1]?.[0] as string) as RequestLogEntry;
    expect(second.status).toBe(404);
    expect(second.path).toBe('/not-found');
  });
});

