  getPaginated(options?: { page?: number; limit?: number }): PaginatedBookmarks {
    const rawPage = options?.page ?? 1;
    const rawLimit = options?.limit ?? 20;

    const page = rawPage < 1 ? 1 : Math.floor(rawPage);
    let limit = rawLimit < 1 ? 1 : Math.floor(rawLimit);
    if (limit > 100) {
      limit = 100;
    }

    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: [...dto.tags] } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

