import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginationInfo {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedBookmarks {
  data: Bookmark[];
  pagination: PaginationInfo;
}

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(message = 'Bookmark not found') {
    super(message);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  create(dto: CreateBookmarkDTO): Bookmark {
    const existing = this.findByUrl(dto.url);
    if (existing) {
      throw new DuplicateBookmarkError(`Bookmark with URL already exists: ${dto.url}`);
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      tags: dto.tags ? [...dto.tags] : [],
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  findById(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  getPaginated(options?: { page?: number; limit?: number }): PaginatedBookmarks {
    const rawPage = options?.page ?? 1;
    const rawLimit = options?.limit ?? 20;

    const page = rawPage < 1 ? 1 : Math.floor(rawPage);
    let limit = rawLimit < 1 ? 1 : Math.floor(rawLimit);
    if (limit > 100) {
      limit = 100;
    }

    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  search(term: string): Bookmark[] {

