  search(term: string): Bookmark[] {
    const trimmed = term.trim();
    if (!trimmed) {
      return [];
    }
    const lowerTerm = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatches = bookmark.title
        ? bookmark.title.toLowerCase().includes(lowerTerm)
        : false;
      const tagMatches = bookmark.tags.some(
        (tag) => tag === trimmed || tag.toLowerCase() === lowerTerm
      );
      return titleMatches || tagMatches;
    });
  }

  update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: [...dto.tags] } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

