  }

  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  getPaginated(options?: { page?: number; limit?: number }): PaginatedBookmarks {
    const rawPage = options?.page ?? 1;
    const rawLimit = options?.limit ?? 20;

    const page = rawPage < 1 ? 1 : Math.floor(rawPage);
    let limit = rawLimit < 1 ? 1 : Math.floor(rawLimit);
    if (limit > 100) {
      limit = 100;
    }

    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  search(term: string): Bookmark[] {
    const trimmed = term.trim();
    if (!trimmed) {
      return [];
    }
    const lowerTerm = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatches = bookmark.title
        ? bookmark.title.toLowerCase().includes(lowerTerm)
        : false;
      const tagMatches = bookmark.tags.some(
        (tag) => tag === trimmed || tag.toLowerCase() === lowerTerm
      );
      return titleMatches || tagMatches;
    });
  }

  update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: [...dto.tags] } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }

