export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates a new bookmark with a unique ID and timestamp.
   *
   * @param dto - Data transfer object containing the URL, optional title, and optional tags.
   * @returns The newly created bookmark.
   * @throws {DuplicateBookmarkError} When a bookmark with the provided URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example Site',
   *   tags: ['web', 'reading'],
   * });
   * console.log(bookmark.id);
   * ```
   */
  create(dto: CreateBookmarkDTO): Bookmark {
    const existing = this.findByUrl(dto.url);
    if (existing) {
      throw new DuplicateBookmarkError(`Bookmark with URL already exists: ${dto.url}`);
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      tags: dto.tags ? [...dto.tags] : [],
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique ID of the bookmark to look up.
   * @returns The matching bookmark, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Alias for getById. Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique ID of the bookmark to look up.
   * @returns The matching bookmark, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.findById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.url);
   * }
   * ```
   */
  findById(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  /**
   * Finds a bookmark by its exact URL.
   *
   * @param url - The exact URL string to search for.
   * @returns The matching bookmark, or undefined if no bookmark matches the URL.
   *
   * @example
   * ```ts
   * const existing = bookmarkService.findByUrl('https://example.com');
   * if (existing) {
   *   console.log('Bookmark already exists with id:', existing.id);
   * }
   * ```
   */
  findByUrl(url: string): Bookmark | undefined {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === url) {
        return bookmark;
      }
    }
    return undefined;
  }

  /**
   * Retrieves all bookmarks sorted by creation time in descending order (newest first).
   *
   * @returns An array of all bookmarks in descending creation order.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * console.log(`Total bookmarks: ${allBookmarks.length}`);
   * ```
   */
  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated slice of bookmarks with metadata.
   *
   * @param options - Optional pagination options specifying page number and item limit.
   * @returns An object containing the slice of bookmarks and pagination metadata.
   *
   * @example
   * ```ts
   * const { data, pagination } = bookmarkService.getPaginated({ page: 1, limit: 10 });
   * console.log(`Page ${pagination.page} of ${pagination.totalPages}, total: ${pagination.total}`);
   * ```
   */
  getPaginated(options?: { page?: number; limit?: number }): PaginatedBookmarks {
    const rawPage = options?.page ?? 1;
    const rawLimit = options?.limit ?? 20;

    const page = rawPage < 1 ? 1 : Math.floor(rawPage);
    let limit = rawLimit < 1 ? 1 : Math.floor(rawLimit);
    if (limit > 100) {
      limit = 100;
    }

    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Searches bookmarks by title (case-insensitive substring match) and tags (exact match).
   *
   * @param term - The query string to search by.
   * @returns An array of matching bookmarks, or an empty array if none match or query is blank.
   *
   * @example
   * ```ts
   * const results = bookmarkService.search('typescript');
   * for (const item of results) {
   *   console.log(item.title, item.tags);
   * }
   * ```
   */
  search(term: string): Bookmark[] {
    const trimmed = term.trim();
    if (!trimmed) {
      return [];
    }
    const lowerTerm = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatches = bookmark.title
        ? bookmark.title.toLowerCase().includes(lowerTerm)
        : false;
      const tagMatches = bookmark.tags.some(
        (tag) => tag === trimmed || tag.toLowerCase() === lowerTerm
      );
      return titleMatches || tagMatches;
    });
  }

  /**
   * Updates an existing bookmark's title and/or tags. URL and ID remain immutable.
   *
   * @param id - The unique ID of the bookmark to update.
   * @param dto - Data transfer object containing optional new title and/or tags.
   * @returns The updated bookmark, or undefined if the bookmark was not found.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'Updated Documentation',
   *   tags: ['docs', 'reference'],
   * });
   * ```
   */
  update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: [...dto.tags] } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Deletes a bookmark by its unique ID.
   *
   * @param id - The unique ID of the bookmark to delete.
   * @returns True if the bookmark existed and was deleted, false otherwise.
   *
   * @example
   * ```ts
   * const wasDeleted = bookmarkService.delete('123e4567-e89b-12d3-a456-426614174000');
   * if (wasDeleted) {
   *   console.log('Bookmark deleted successfully');
   * }
   * ```
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Removes all bookmarks from memory.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * console.log(bookmarkService.getAll().length); // 0
   * ```
   */
  clear(): void {
    this.bookmarks.clear();
  }

